var renderer=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<UnityEngine.Renderer>(true)).First(r=>r.name=="Sprout");return new{size=renderer.bounds.size.ToString(),materials=renderer.sharedMaterials.Where(m=>m!=null).Select(m=>new{name=m.name,path=UnityEditor.AssetDatabase.GetAssetPath(m),textures=m.GetTexturePropertyNames().Select(p=>new{property=p,texture=m.GetTexture(p)?.name}).ToArray()}).ToArray()};
